                Keywords = new[] { "iss", "space station", "international space station", "astronauts live" },
                Fact = "The International Space Station is a football-field-sized laboratory orbiting about 400 km above Earth at 28,000 km/h — it circles the whole planet every 90 minutes. Astronauts have lived aboard continuously since the year 2000. You can see it with your bare eyes: it looks like a bright star gliding across the sky for a few minutes." },
            new() { Topic = "What satellites do",
