                Fact = "Space is silent. Sound needs air or water to travel through, and space is almost perfectly empty, so there is nothing to carry it. A movie explosion in space would really happen without a whisper — astronauts talk by radio, which works fine in a vacuum." },
            new() { Topic = "Brontosaurus",
                Keywords = new[] { "brontosaurus", "brontosorus", "brontosaurs", "thunder lizard" },
                Fact = "Brontosaurus, the 'thunder lizard', was a giant long-necked plant-eater of the Jurassic, about 22 metres long. For decades scientists filed it under Apatosaurus, but a 2015 study brought the name Brontosaurus back as its own genus — one of palaeontology's most famous comebacks." },
            new() { Topic = "Why the moon has craters",
                Keywords = new[] { "moon craters", "why does the moon have craters", "holes on the moon" },
                Fact = "The moon's craters are scars from asteroids and comets that crashed into it over billions of years. With no air, rain or wind, nothing wears them away — even the Apollo astronauts' footprints will last millions of years." },
            new() { Topic = "The biggest stars",
                Keywords = new[] { "biggest star", "largest star", "biggest sun" },
                Fact = "The biggest known stars, like UY Scuti and Stephenson 2-18, are so huge that if one replaced our Sun its surface would reach past Jupiter. Betelgeuse, the red giant on Orion's shoulder, would swallow everything out to the asteroid belt." },
            new() { Topic = "If the moon disappeared",
                Keywords = new[] { "moon disappeared", "moon vanished", "without the moon", "no moon", "moon was gone", "moon exploded", "moon disappear" },
                Fact = "If the moon vanished, the ocean tides would shrink to about a third of their size, nights would be much darker, and over millions of years Earth's tilt would wobble, scrambling the seasons. Days would even slowly change length — the moon quietly keeps Earth steady." },
            new() { Topic = "What a constellation is",
                Keywords = new[] { "what is a constellation", "constellations", "star patterns", "pictures in the stars" },
                Fact = "A constellation is a pattern people draw between stars, like a join-the-dots picture — Orion the hunter, Leo the lion. Its stars aren't really together; some are near, some far, they only line up from where Earth sits. Astronomers use 88 official constellations to map the whole sky." },
            // ---------------- space history & missions ----------------
            new() { Topic = "The moon landing",
                Keywords = new[] { "first on the moon", "first man on the moon", "moon landing", "apollo 11", "neil armstrong", "who walked on the moon", "landed on the moon", "went to the moon first", "first moon landing", "who was first on the moon" },
                Fact = "Neil Armstrong was the first person to walk on the moon, on July 20, 1969, during NASA's Apollo 11 mission. Buzz Aldrin stepped out just after him while Michael Collins orbited above in the spaceship. Armstrong's first words were 'That's one small step for man, one giant leap for mankind.'" },
            new() { Topic = "How many people walked on the moon",
                Keywords = new[] { "how many people walked on the moon", "how many astronauts moon", "people on the moon", "walked on the moon", "last person on the moon" },
                Fact = "Twelve astronauts have walked on the moon, all between 1969 and 1972 on NASA's Apollo missions. The last was Gene Cernan on Apollo 17 in December 1972. Nobody has been back since — but new missions are being built to return." },
            new() { Topic = "Will we go back to the moon",
                Keywords = new[] { "go back to the moon", "return to the moon", "artemis", "going to the moon again", "moon again", "new moon mission", "will we go to the moon" },
                Fact = "Yes — NASA's Artemis program is working to land astronauts on the moon again, including the first woman to walk there. The plan is to build a small station near the moon and learn to live on another world, as practice for Mars." },
            new() { Topic = "Will humans go to Mars",
                Keywords = new[] { "will we ever go to mars", "will we go to mars", "go to mars", "going to mars", "travel to mars", "humans to mars", "mars mission", "when will people go to mars", "get to mars", "visit mars", "fly to mars" },
                Fact = "Very likely yes — space agencies and companies are working on it right now. A trip to Mars takes about seven to nine months one way, so the crew needs food, water, radiation shielding and a way home. Many scientists think the first boots on Mars could happen in your lifetime." },
            new() { Topic = "How long to get to Mars",
                Keywords = new[] { "how long to get to mars", "how long does it take to get to mars", "how far to mars", "trip to mars", "long to reach mars" },
                Fact = "With today's rockets a one-way trip to Mars takes about seven to nine months, and you can only leave when Earth and Mars line up nicely — about every 26 months. That's why a whole Mars trip, there and back, would take around three years." },
            new() { Topic = "Mars rovers",
                Keywords = new[] { "mars rover", "rover on mars", "curiosity", "perseverance", "robots on mars", "ingenuity", "helicopter on mars", "whats on mars right now" },
                Fact = "Robot rovers explore Mars for us. Curiosity and Perseverance are car-sized laboratories on wheels that study rocks, look for signs of ancient water and life, and send photos home every day. Perseverance even brought a little helicopter, Ingenuity, that made the first flight on another planet." },
            new() { Topic = "First person in space",
                Keywords = new[] { "first person in space", "first man in space", "yuri gagarin", "gagarin", "first human in space", "who went to space first", "first in space" },
                Fact = "Yuri Gagarin, a Soviet cosmonaut, was the first human in space. On April 12, 1961 he orbited Earth once in his little spherical ship Vostok 1 — the whole flight took 108 minutes. His callsign smile made him famous around the world." },
            new() { Topic = "First woman in space",
                Keywords = new[] { "first woman in space", "valentina tereshkova", "tereshkova", "first girl in space", "sally ride", "women in space", "female astronaut" },
                Fact = "Valentina Tereshkova became the first woman in space in 1963, orbiting Earth 48 times. Twenty years later Sally Ride became the first American woman in space. Today women fly on nearly every space station crew, and one will walk on the moon with Artemis." },
            new() { Topic = "The first satellite",
                Keywords = new[] { "sputnik", "first satellite", "first thing in space", "first spacecraft", "space race" },
                Fact = "Sputnik 1, launched by the Soviet Union on October 4, 1957, was the first human-made satellite. It was a shiny metal ball the size of a beach ball that beeped radio signals as it circled Earth — and it kicked off the Space Race that led to the moon landings." },
            new() { Topic = "Apollo 13",
                Keywords = new[] { "apollo 13", "houston we have a problem", "space rescue", "moon mission that failed" },
                Fact = "Apollo 13 was meant to land on the moon in 1970, but an oxygen tank exploded on the way. The three astronauts moved into their tiny lunar lander like a lifeboat, swung around the moon, and made it home safely — one of the greatest rescues ever. That's where 'Houston, we've had a problem' comes from." },
            new() { Topic = "Voyager probes",
                Keywords = new[] { "voyager", "voyager 1", "voyager 2", "farthest spacecraft", "interstellar", "golden record" },
                Fact = "Voyager 1 and 2 launched in 1977, flew past the giant planets, and are now the farthest human-made things ever — beyond the planets, in interstellar space. Each carries a Golden Record with pictures, music and greetings from Earth, a message in a bottle for anyone who finds it." },
            new() { Topic = "Space telescopes",
                Keywords = new[] { "hubble", "james webb", "space telescope", "jwst", "webb telescope", "how do we see far in space" },
                Fact = "Space telescopes look at the universe from above Earth's blurry air. Hubble has taken breathtaking pictures for over 30 years, and the James Webb Space Telescope sees in infrared — it can look at baby galaxies from near the beginning of time and sniff the air of planets around other stars." },
            new() { Topic = "Reusable rockets",
                Keywords = new[] { "spacex", "falcon 9", "reusable rocket", "rockets that land", "starship", "why do rockets land" },
                Fact = "New rockets can land themselves and fly again. Boosters like SpaceX's Falcon 9 come back from the edge of space and touch down on legs, which makes spaceflight much cheaper — like reusing a plane instead of throwing it away after one flight. Giant fully-reusable ships are being tested for the moon and Mars." },
            new() { Topic = "What is NASA",
                Keywords = new[] { "what is nasa", "nasa", "space agency", "who sends rockets" },
                Fact = "NASA is the United States' space agency — the people behind the Apollo moon landings, the Mars rovers, the Hubble telescope and much more. Other countries have agencies too, like ESA in Europe, and they often work together on the International Space Station." },
            new() { Topic = "How astronauts train",
                Keywords = new[] { "how do astronauts train", "become an astronaut", "astronaut training", "how do you become an astronaut", "want to be an astronaut" },
                Fact = "Astronauts train for years: they practise spacewalks underwater in a giant pool, fly jets, study engineering and medicine, and rehearse every emergency in simulators. Most started out as pilots, scientists, engineers or doctors — so doing well in school is genuinely step one." },
            new() { Topic = "Spacesuits",
                Keywords = new[] { "spacesuit", "space suit", "why do astronauts wear suits", "what do astronauts wear" },
                Fact = "A spacesuit is a one-person spaceship. It holds air to breathe, water to sip, heaters and coolers, and armour against radiation and speeding dust. The backpack is the life-support machine — without a suit, an astronaut couldn't survive outside for even a minute." },
            new() { Topic = "Floating in space",
                Keywords = new[] { "why do astronauts float", "weightless", "zero gravity", "no gravity in space", "floating in space", "microgravity" },
                Fact = "Astronauts float because they're falling! The space station and everyone inside are falling around Earth together, so nothing presses on anything — that's weightlessness. Gravity up there is still almost as strong as on the ground; they're just falling sideways so fast they keep missing the Earth." },
            new() { Topic = "How far is the moon",
                Keywords = new[] { "how far is the moon", "distance to the moon", "how far away is the moon", "how long to get to the moon" },
                Fact = "The moon is about 384,000 kilometres away — around 30 Earths lined up in a row. Apollo astronauts took about three days to fly there. Light makes the trip in just 1.3 seconds." },
            new() { Topic = "How far is the sun",
                Keywords = new[] { "how far is the sun", "distance to the sun", "how far away is the sun" },
                Fact = "The Sun is about 150 million kilometres away — a distance astronomers call one astronomical unit. Sunlight takes 8 minutes and 20 seconds to reach us, so you always see the Sun as it looked eight minutes ago." },
            new() { Topic = "What is an orbit",
                Keywords = new[] { "what is an orbit", "why do planets orbit", "why does the moon orbit", "what keeps planets moving", "why doesnt the moon fall", "why do planets go around the sun" },
                Fact = "An orbit is falling and missing. The moon is pulled toward Earth by gravity, but it's also moving sideways so fast that it keeps missing — so it loops around forever. Planets do the same around the Sun. If they stopped moving sideways, they really would fall in!" },
            new() { Topic = "The closest star",
                Keywords = new[] { "closest star", "nearest star", "proxima centauri", "alpha centauri", "how far is the nearest star" },
                Fact = "After the Sun, the nearest star is Proxima Centauri, about 4.2 light-years away. Even our fastest spacecraft would take tens of thousands of years to reach it. It has at least one planet, which makes astronomers very curious." },
            new() { Topic = "What is an exoplanet",
                Keywords = new[] { "exoplanet", "planets around other stars", "other solar systems", "planets outside", "how many planets in the universe" },
                Fact = "An exoplanet is a planet around another star. Astronomers have confirmed more than 5,000 of them — hot giants, lava worlds, ice worlds, and some rocky planets at just the right distance for liquid water. Most stars you see at night probably have planets." },
            new() { Topic = "What is a dwarf planet",
                Keywords = new[] { "dwarf planet", "what is pluto now", "ceres", "eris" },
                Fact = "A dwarf planet is round like a planet but hasn't cleared other rocks out of its orbital lane. Pluto is the most famous one; Ceres, Eris, Haumea and Makemake are dwarf planets too. They're real worlds — just in a smaller league." },
            new() { Topic = "Why Saturn has rings",
                Keywords = new[] { "why does saturn have rings", "what are saturns rings made of", "saturn rings", "rings of saturn" },
                Fact = "Saturn's rings are billions of chunks of ice and rock, from dust-size to house-size, all orbiting in a sheet thinner than a football field. They're probably the crumbs of a shattered moon or comet. One day, far in the future, they'll rain down and fade away." },
            new() { Topic = "Jupiter's Great Red Spot",
                Keywords = new[] { "great red spot", "jupiters storm", "red spot", "storm on jupiter" },
                Fact = "Jupiter's Great Red Spot is a storm bigger than the whole Earth that has been spinning for at least 200 years. Its winds blow over 400 km/h. It's slowly shrinking, and nobody knows exactly when it might finally die out." },
            new() { Topic = "Water in space",
                Keywords = new[] { "water on mars", "water on the moon", "water in space", "ice in space", "is there water on other planets" },
                Fact = "Water is surprisingly common in space — just usually frozen. Mars has ice caps and once had rivers and lakes; the moon hides ice in its dark polar craters; and moons like Europa and Enceladus have entire oceans under their icy shells. Where there's water, there might be life." },
            new() { Topic = "Moon gravity",
                Keywords = new[] { "gravity on the moon", "jump on the moon", "moon gravity", "how high can you jump on the moon", "why did astronauts bounce" },
                Fact = "The moon's gravity is about one-sixth of Earth's. If you can jump half a metre here, you could leap about three metres there — which is why Apollo astronauts bounced like kangaroos. But there's no air, so you'd still need your suit." },
            new() { Topic = "Does the moon have air",
                Keywords = new[] { "does the moon have air", "atmosphere on the moon", "can you breathe on the moon", "is there wind on the moon" },
                Fact = "The moon has almost no air at all — no wind, no weather, no sound. That's why astronaut footprints from 1969 are still there today, sharp as the day they were made, and why the sky is black even at lunar noon." },
            new() { Topic = "What is the atmosphere",
                Keywords = new[] { "what is the atmosphere", "why does earth have air", "what is air made of", "how thick is the atmosphere" },
                Fact = "The atmosphere is Earth's blanket of air — mostly nitrogen and oxygen. It gives us weather, spreads the Sun's warmth, burns up meteors, and blocks harmful rays. Compared to the whole planet it's as thin as the skin on an apple." },
            new() { Topic = "Day and night",
                Keywords = new[] { "why is there day and night", "why does the sun rise", "why does the sun set", "where does the sun go" },
                Fact = "Earth spins like a top, once every 24 hours. When your side of the planet faces the Sun it's daytime; when it turns away, it's night. The Sun never actually goes anywhere — you do!" },
            new() { Topic = "What is inside Earth",
                Keywords = new[] { "what is inside the earth", "earths core", "center of the earth", "middle of the earth", "how hot is the core" },
                Fact = "Earth is built in layers like an onion: the thin rocky crust we live on, a slowly-churning hot mantle, and a metal core. The inner core is a solid iron ball about as hot as the surface of the Sun — around 5,500 degrees Celsius." },
            new() { Topic = "What is a leap year",
                Keywords = new[] { "leap year", "why does february have 29", "extra day" },
                Fact = "Earth actually takes about 365 and a quarter days to circle the Sun. Those quarter-days pile up, so every four years we add February 29 to keep the calendar matched to Earth's orbit. That's a leap year." },
            new() { Topic = "The asteroid belt",
                Keywords = new[] { "asteroid belt", "where are the asteroids", "belt between mars and jupiter" },
                Fact = "The asteroid belt is a ring of rocky leftovers between Mars and Jupiter — pieces of a planet that never finished forming because Jupiter's gravity kept stirring them up. Despite the movies, it's mostly empty space; spacecraft fly through it without a scratch." },
            new() { Topic = "Space junk",
                Keywords = new[] { "space junk", "space debris", "trash in space", "old satellites" },
                Fact = "Thousands of dead satellites, old rocket parts and tiny fragments are whizzing around Earth — that's space junk. Even a paint fleck moving at 28,000 km/h can chip a window, so agencies track the pieces and are inventing ways to clean up." },
            new() { Topic = "Why the sun is dangerous to look at",
